//! 💠️ Full literal parent and managed mesh owners share one exact cell visitor and paid row index.
use crate::standards::v1::subsets::any::schema::snapshot::LowpolySnapshot;
use crate::{LowpolyObject,LowpolyTransform,LowpolyPaintLayer};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,artifact::{RowWriter,Cell,FloatColumn,FloatRow}}};
use semio_framework_value::{DecodedValue,FromValue,NativeDecodeControl,ValueError,ValueRefusalKind};
#[path="🕸️mesh/🛫️projection/🦀️.rs"]mod mesh_projection;
#[path="🕸️mesh/🔍️rows/🦀️.rs"]mod rows;
#[path="🕸️mesh/🛬️reconstruction/🦀️.rs"]mod mesh_reconstruction;
#[path="🕸️mesh/📏️preflight/🦀️.rs"]mod preflight;
const TRANSFORM:&[FloatColumn]=&[FloatColumn::Binary32(1),FloatColumn::Binary32(2),FloatColumn::Binary32(3),FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6),FloatColumn::Binary32(7),FloatColumn::Binary32(8),FloatColumn::Binary32(9)];
const OPACITY:&[FloatColumn]=&[FloatColumn::Binary32(5)];
fn invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn ordinal(value:usize)->Result<i64,ValueError>{i64::try_from(value).map_err(|_|invalid("Lowpoly occurrence exceeds signed SQLite ordinal"))}
fn boolean(row:&store::sqlite_snapshot::SqliteRow,column:usize)->Result<bool,ValueError>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("Lowpoly boolean exceeds its domain"))}}
fn retire_snapshot(mut owner:LowpolySnapshot){for object in&mut owner.objects{if let Some(mut state)=object.mesh_state.take(){for attribute in&mut state.attributes{for value in attribute.values.drain(..){value.retire_decoded();}}for material in state.materials.drain(..){material.value.retire_decoded();}}}}

fn write(snapshot:&LowpolySnapshot,writer:&mut RowWriter<'_,'_>)->Result<(),ValueError>{writer.insert_key("lowpoly_document",1,&[Cell::Text(&snapshot.schema)])?;
 for(at,object)in snapshot.objects.iter().enumerate(){let at=ordinal(at)?;let id=at.checked_add(1).ok_or_else(||invalid("Lowpoly object identity overflow"))?;writer.insert_key("lowpoly_object",id,&[Cell::Integer(1),Cell::Integer(at),Cell::Text(&object.id),Cell::Text(&object.name),Cell::Integer(i64::from(object.smooth_shading)),Cell::Text(&object.mesh_content)])?;let transform=&object.transform;writer.insert_key_float("lowpoly_transform",id,&[Cell::Float32(transform.position[0]),Cell::Float32(transform.position[1]),Cell::Float32(transform.position[2]),Cell::Float32(transform.rotation[0]),Cell::Float32(transform.rotation[1]),Cell::Float32(transform.rotation[2]),Cell::Float32(transform.scale[0]),Cell::Float32(transform.scale[1]),Cell::Float32(transform.scale[2])],TRANSFORM)?;
  if let Some(child)=&object.mesh{writer.insert_key("lowpoly_mesh_child",id,&[Cell::Text(&child.child_id),Cell::Text(&child.target.artifact_id),Cell::Text(&child.target.dialect.artifact_kind),Cell::Text(&child.target.dialect.standard),Cell::Text(&child.target.dialect.subset)])?;}
  for(at,layer)in object.paint_layers.iter().enumerate(){let id=writer.insert_float("lowpoly_paint_layer",&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Text(&layer.name),Cell::Integer(i64::from(layer.visible)),Cell::Float32(layer.opacity),Cell::Text(&layer.blend_mode)],OPACITY)?;for(at,byte)in layer.pixels.iter().enumerate(){writer.insert("lowpoly_paint_octet",&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(*byte))])?;}}
  if let Some(state)=&object.mesh_state{mesh_projection::project(state,id,writer)?;}
 }Ok(())
}
fn admit(snapshot:&LowpolySnapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut writer=RowWriter::borrowed(control,phase)?;write(snapshot,&mut writer)?;writer.finish_borrowed()}
fn reconstruct(database:&SqliteDatabase,native:&mut NativeDecodeControl<'_>)->Result<LowpolySnapshot,ValueError>{native.scoped_stage(|native|{native.begin_stage(0)?;let mut rows=rows::Rows::new(database,native)?;if rows.len("lowpoly_document")?!=1{return Err(invalid("Lowpoly document cardinality differs"))}let document=rows.sole("lowpoly_document",native)?;let objects=rows.group("lowpoly_object",document.rowid,native)?;let mut result=DecodedValue::new(LowpolySnapshot{schema:native.copy_text(document.text(1)?)?,objects:native.allocate_vec(objects.len())?},retire_snapshot);
 for row in objects{native.step()?;let scalar=FloatRow::new(rows.take("lowpoly_transform",row.rowid,native)?,TRANSFORM)?;let transform=LowpolyTransform{position:[scalar.binary32(1)?,scalar.binary32(2)?,scalar.binary32(3)?],rotation:[scalar.binary32(4)?,scalar.binary32(5)?,scalar.binary32(6)?],scale:[scalar.binary32(7)?,scalar.binary32(8)?,scalar.binary32(9)?]};let mesh=if rows.contains("lowpoly_mesh_child",row.rowid){let child=rows.take("lowpoly_mesh_child",row.rowid,native)?;Some(store::ArtifactChild::new(native.copy_text(child.text(1)?)?,semio_framework_artifact_reference::ArtifactRef{artifact_id:native.copy_text(child.text(2)?)?,dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:native.copy_text(child.text(3)?)?,standard:native.copy_text(child.text(4)?)?,subset:native.copy_text(child.text(5)?)?}}))}else{None};let layers=rows.group("lowpoly_paint_layer",row.rowid,native)?;let mut paint_layers=native.allocate_vec(layers.len())?;
  for layer in layers{native.step()?;let source=rows.group("lowpoly_paint_octet",layer.rowid,native)?;let mut pixels=native.allocate_vec(source.len())?;for octet in source{native.step()?;pixels.push(u8::try_from(octet.integer(3)?).map_err(|_|invalid("Lowpoly paint sample exceeds octet"))?);}paint_layers.push(LowpolyPaintLayer{name:native.copy_text(layer.text(3)?)?,visible:boolean(layer,4)?,opacity:FloatRow::new(layer,OPACITY)?.binary32(5)?,blend_mode:native.copy_text(layer.text(6)?)?,pixels});}
  let id=native.copy_text(row.text(3)?)?;let name=native.copy_text(row.text(4)?)?;let smooth_shading=boolean(row,5)?;let mesh_content=native.copy_text(row.text(6)?)?;let mesh_state=mesh_reconstruction::reconstruct(row.rowid,&mut rows,native)?;result.get_mut().objects.push(LowpolyObject{id,name,transform,smooth_shading,mesh,paint_layers,mesh_content,mesh_state});
 }rows.finish(native)?;native.checkpoint()?;Ok(result.take())})}
impl ArtifactSqliteSnapshot for LowpolySnapshot{
 const SQLITE_SCHEMA:&'static str=concat!(include_str!("🗄️.sql"),"\n",include_str!("🕸️mesh/🗄️.sql"));
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{admit(self,SqliteSnapshotPhase::EncodeNative,control)?;let mut bound=store::sqlite_snapshot::artifact::NativeEncodingBound::new(control)?;bound.add(4096)?;bound.repeated(self.schema.len(),12)?;for object in&self.objects{bound.add(4096)?;for value in[&object.id,&object.name,&object.mesh_content]{bound.repeated(value.len(),12)?;}if let Some(child)=&object.mesh{bound.add(2048)?;for value in[&child.child_id,&child.target.artifact_id,&child.target.dialect.artifact_kind,&child.target.dialect.standard,&child.target.dialect.subset]{bound.repeated(value.len(),12)?;}}for layer in&object.paint_layers{bound.add(2048)?;bound.repeated(layer.name.len(),12)?;bound.repeated(layer.blend_mode.len(),12)?;bound.repeated(layer.pixels.len(),8)?;}if let Some(mesh)=&object.mesh_state{preflight::mesh(mesh,&mut bound)?;}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut writer=RowWriter::new(Self::SQLITE_SCHEMA,control)?;write(self,&mut writer)?;writer.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;store::sqlite_snapshot::validate_sqlite_database_schema_controlled(database,Self::SQLITE_SCHEMA,SqliteSnapshotPhase::ReconstructSnapshot,control)?;control.allocation_stage(SqliteSnapshotPhase::ReconstructSnapshot,|allowance,progress,allocation|{let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|progress(event.completed,event.total);let mut native_allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|allocation(request.bytes);let mut native=NativeDecodeControl::new_forwarded(allowance,&mut callback,&mut native_allocation);let result=reconstruct(database,&mut native);(result,native.owned_bytes())})?}
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>,native_owner:&mut semio_framework_os_kernel::NativeSnapshotEncodeOwner<'_, '_>)->Result<store::io_schema::IoPayload,ValueError>{admit(self,SqliteSnapshotPhase::EncodeNative,control)?;store::encode_sqlite_snapshot_record_native(encoding,"lowpoly.lowpoly",Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control,native_owner)}
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_control: &mut semio_framework_os_kernel::NativeSnapshotDecodeOwner<'_, '_>)->Result<Self,ValueError>{let owner=DecodedValue::new(store::decode_sqlite_snapshot_record_native(payload,"lowpoly.lowpoly",Self::__dsl_spec_producer(),|record, snapshot_output, native,_body| { let constructed: Result<_, semio_framework_value::ValueError> = (|| {Self::__dsl_from_record_controlled(record,native)})(); *snapshot_output = Some(constructed?); Ok(()) },control,native_control)?,retire_snapshot);admit(owner.get(),SqliteSnapshotPhase::DecodeNative,control)?;Ok(owner.take())}
 fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.lowpoly.lowpoly"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("Lowpoly does not own this semantic subset")))}let candidate=DecodedValue::new(Self::from_sqlite_database(database,control).map_err(store::io_schema::IoError::from_value_error)?,retire_snapshot);if candidate.get().to_sqlite_database(control).map_err(store::io_schema::IoError::from_value_error)?!=self.to_sqlite_database(control).map_err(store::io_schema::IoError::from_value_error)?{return Err(store::io_schema::IoError::from_value_error(invalid("Lowpoly logical snapshot state differs")))}Ok(store::io_schema::IoOutcome::clean(()))}
}

